def merge_sorted_streams(*streams):
    import heapq

    # Iterator that yields (key, value) pairs from a single stream,
    # keeping only the last occurrence of each key.
    def last_occurrence(stream):
        last = {}
        for k, v in stream:
            last[k] = v
        for k in sorted(last):
            yield (k, last[k])

    # Wrap each input stream with the above helper.
    wrapped = [last_occurrence(s) for s in streams]

    # Build a heap of the current (key, stream_index) for each non‑empty iterator.
    heap = []
    for idx, it in enumerate(wrapped):
        try:
            first = next(it)
            heapq.heappush(heap, (first[0], idx, first))
        except StopIteration:
            pass  # empty stream

    # Merge while preserving the “last value wins” rule.
    while heap:
        key, idx, item = heapq.heappop(heap)
        # Yield the current item (the latest value for this key seen so far).
        yield (key, item[1])

        # Pull the next item from the same stream, if any, and push it.
        try:
            nxt = next(wrapped[idx])
            heapq.heappush(heap, (nxt[0], idx, nxt))
        except StopIteration:
            pass
